operations.exampleQuery:
mutation createToken($login: String!, $password: String!) {
  createToken(login: $login, password: $password) {
    token
  }
}

query orders($currentPage: Int, $perPage: Int, $imported: Boolean, $industryCode: String, $orderCode: Int, $status: OrderStatusEnum, $notificationStatus: NotificationStatusEnum, $beginDate: Date, $endDate: Date, $source: OrderSourceEnum, $wholesalerBranchCode: String, $id: Int, $customerCode: String) {
  orders(current_page: $currentPage, per_page: $perPage, imported: $imported, industry_code: $industryCode, order_code: $orderCode, status: $status, notification_status: $notificationStatus, filter: { begin_date: $beginDate, end_date: $endDate }, source: $source, wholesaler_branch_code: $wholesalerBranchCode, id: $id, customer_code: $customerCode) {
    total
    from
    to
    data {
      id
      status
      order_code
      tradetools_created_at
      notification_obs
      notification_status
      industry_code
      customer_code
      customer_alternative_code
      distribution_center_code
      products {
        ean
        amount
        discount_percentage
        net_value
        monitored
        payment_term
      }
      responses { id importation_outcome consideration_code }
      invoices { id importation_status importation_outcome status processed_at released_on danfe_key code value discount products_total_value }
      cancellations { id imported_at outcome }
    }
  }
}

mutation setOrderAsImported($id: Int, $orderCode: Int, $industryCode: String) {
  setOrderAsImported(id: $id, order_code: $orderCode, industry_code: $industryCode) {
    id
    order_code
    customer_code
    customer_alternative_code
  }
}

mutation createResponse($industryCode: String!, $orderCode: Int!, $wholesalerCode: String!, $wholesalerOrderCode: String, $paymentTerm: String, $reason: OrderMotiveEnum, $consideration: String, $isFreeGoodDiscount: Boolean, $processedAt: String!, $invoiceAt: String, $deliveryForecastAt: String, $products: [ResponseProductInput!]!) {
  createResponse(industry_code: $industryCode, order_code: $orderCode, wholesaler_code: $wholesalerCode, wholesaler_order_code: $wholesalerOrderCode, payment_term: $paymentTerm, reason: $reason, consideration: $consideration, is_free_good_discount: $isFreeGoodDiscount, processed_at: $processedAt, invoice_at: $invoiceAt, delivery_forecast_at: $deliveryForecastAt, products: $products) {
    id
    content
    imported_at
    outcome
  }
}

query order($industryCode: String!, $orderCode: Int!) {
  order(industry_code: $industryCode, order_code: $orderCode) {
    id
    order_code
    tradetools_created_at
    industry_code
    wholesaler_branch_code
    customer_code
    notification_obs
    notification_status
    status
    products { ean stock_type amount discount_percentage }
    responses { id importation_outcome consideration_code products { ean invoice_ean response_amount unit_discount_percentage unit_discount_value unit_net_value monitored industry_consideration wholesaler_consideration } }
    invoices { id importation_status importation_outcome status processed_at released_on danfe_key code value discount products_total_value products { ean invoice_amount unit_discount_percentage } reimbursement_values { ean value formula formula_variables } }
    cancellations { id imported_at outcome }
  }
}

mutation createInvoice($industryCode: String!, $orderCode: Int!, $wholesalerCode: String!, $customerCode: String!, $wholesalerOrderCode: String, $processedAt: String!, $invoiceReleasedOn: String!, $invoiceCode: String!, $taxSubstitutionIcmsTaxCalcBase: Float, $icmsTaxCalcBase: Float, $invoiceModel: String, $invoiceSeries: String, $invoiceDanfeKey: String!, $invoiceValue: Float!, $invoiceDiscount: Float!, $invoicePassedAlongIcmsTaxValue: Float, $invoiceProductsTotalValue: Float, $invoiceIpiTaxValue: Float, $invoiceFreightValue: Float, $invoiceInsuranceValue: Float, $invoiceIcmsTaxTotalValue: Float, $invoiceIcmsTaxRetainedTotalValue: Float, $invoiceVolumeAmount: Float, $products: [InvoiceProductInput!]!, $taxes: [InvoiceTaxRateWEInputType], $batches: [invoiceBatchWEInputType], $bankTickets: [InvoiceBankTicketWEInputType], $totalInvoices: Int, $invoiceCount: Int) {
  createInvoice(industry_code: $industryCode, order_code: $orderCode, wholesaler_code: $wholesalerCode, customer_code: $customerCode, wholesaler_order_code: $wholesalerOrderCode, processed_at: $processedAt, invoice_released_on: $invoiceReleasedOn, invoice_code: $invoiceCode, tax_substitution_icms_tax_calc_base: $taxSubstitutionIcmsTaxCalcBase, icms_tax_calc_base: $icmsTaxCalcBase, invoice_model: $invoiceModel, invoice_series: $invoiceSeries, invoice_danfe_key: $invoiceDanfeKey, invoice_value: $invoiceValue, invoice_discount: $invoiceDiscount, invoice_passed_along_icms_tax_value: $invoicePassedAlongIcmsTaxValue, invoice_products_total_value: $invoiceProductsTotalValue, invoice_ipi_tax_value: $invoiceIpiTaxValue, invoice_freight_value: $invoiceFreightValue, invoice_insurance_value: $invoiceInsuranceValue, invoice_icms_tax_total_value: $invoiceIcmsTaxTotalValue, invoice_icms_tax_retained_total_value: $invoiceIcmsTaxRetainedTotalValue, invoice_volume_amount: $invoiceVolumeAmount, products: $products, taxes: $taxes, batches: $batches, bank_tickets: $bankTickets, total_invoices: $totalInvoices, invoice_count: $invoiceCount) {
    id
    content
    imported_at
    outcome
  }
}

mutation createCancellation($orderCode: Int!, $industryCode: String!, $wholesalerBranchCode: String!, $entirelyCancelled: Boolean, $products: [CancellationProductInput]) {
  createCancellation(order_code: $orderCode, industry_code: $industryCode, wholesaler_branch_code: $wholesalerBranchCode, entirely_cancelled: $entirelyCancelled, products: $products) {
    id
    content
    imported_at
    outcome
  }
}

query responses($currentPage: Int, $perPage: Int, $imported: Boolean, $industryCode: String, $orderCode: Int) {
  responses(current_page: $currentPage, per_page: $perPage, imported: $imported, industry_code: $industryCode, order_code: $orderCode) {
    total
    per_page
    current_page
    data { id order_code imported_at outcome wholesaler_branch_code industry_code products { ean response_amount unit_discount_percentage unit_discount_value unit_net_value } }
  }
}

query invoices($currentPage: Int, $perPage: Int, $imported: Boolean, $industryCode: String, $orderCode: Int, $withReversal: Boolean) {
  invoices(current_page: $currentPage, per_page: $perPage, imported: $imported, industry_code: $industryCode, order_code: $orderCode, with_reversal: $withReversal) {
    total
    per_page
    current_page
    data { id order_code imported_at outcome wholesaler_branch_code industry_code products { ean unit_discount_percentage unit_discount_value unit_net_value } reimbursement_values { ean value formula formula_variables } }
  }
}

mutation createBranchPrices($wholesalerBranchCode: String!, $industryCode: String!, $products: [BranchPriceInput!]!) {
  createBranchPrices(wholesaler_branch_code: $wholesalerBranchCode, industry_code: $industryCode, products: $products) {
    id
    content
    imported_at
    importation_status
    importation_outcome
    wholesaler_branch_code
    industry_code
  }
}

query pricingsSearch($currentPage: Int, $perPage: Int, $id: Int, $createdAt: Date, $importDatetime: Datetime, $importAttempts: Int, $importStatus: ImportationStatusEnum, $industryCode: String, $wholesalerCode: String, $wholesalerBranchCode: String, $productCode: String, $regionCode: String) {
  pricingsSearch(currentPage: $currentPage, perPage: $perPage, filter: { id: $id, created_at: $createdAt, import: { datetime: $importDatetime, attempts: $importAttempts, status: $importStatus }, industry: { code: $industryCode }, wholesaler: { code: $wholesalerCode }, wholesaler_branch: { code: $wholesalerBranchCode }, product: { code: $productCode }, region_code: $regionCode }) {
    data { id imported_at industry_code content { products { productCode } } wholesaler { code branches { code } } importation_status importation_outcome created_at updated_at }
    total
    per_page
    current_page
    from
    last_page
    has_more_pages
  }
}

mutation createInvoiceReversal($industryCode: String!, $orderCode: Int!, $newInvoices: [InvoiceInputType!]!) {
  createInvoiceReversal(industry_code: $industryCode, order_code: $orderCode, new_invoices: $newInvoices) {
    id
    imported_at
    outcome
    industry_code
    order_code
  }
}

mutation createDevolution($customerCode: String!, $wholesalerBranchCode: String!, $industryCode: String!, $invoiceNumber: String!, $invoiceNumberDevolution: String!, $invoiceDevolutionCreatedAt: Date, $cfop: String, $danfe: String, $orderCode: Int!, $products: [DevolutionProductInputType!]!) {
  createDevolution(customer_code: $customerCode, wholesaler_branch_code: $wholesalerBranchCode, industry_code: $industryCode, invoice_number: $invoiceNumber, invoice_number_devolution: $invoiceNumberDevolution, invoice_devolution_created_at: $invoiceDevolutionCreatedAt, cfop: $cfop, danfe: $danfe, order_code: $orderCode, products: $products) {
    id
    content
    imported_at
    order_code
    importation_outcome
    outcome
    industry_code
    wholesaler_branch_code
    importation_status
    created_at
    products { ean quantity batch code_reason }
  }
}

query devolutions($currentPage: Int, $perPage: Int, $imported: Boolean, $industryCode: String, $orderCode: Int) {
  devolutions(current_page: $currentPage, per_page: $perPage, imported: $imported, industry_code: $industryCode, order_code: $orderCode) {
    data { id imported_at order_code industry_code wholesaler_branch_code importation_status products { ean quantity batch code_reason } }
    total
    per_page
    current_page
  }
}

query devolution($id: Int!, $imported: Boolean) {
  devolution(id: $id, imported: $imported) {
    id
    imported_at
    order_code
    industry_code
    wholesaler_branch_code
    importation_status
    created_at
  }
}
